import java.io.*;import java.nio.file.*;import java.util.*;
public class TreeLibraryTest {
 static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 static TerrainGraph forest(){var g=new TerrainGraph();var h=g.add(TerrainGraph.Type.CONSTANT,20,20);h.values.put("height",80.0);var trees=g.add(TerrainGraph.Type.TREES,270,20);trees.values.put("density",1.0);trees.values.put("spacing",16.0);g.connect(h.id,trees.id,0);var output=g.add(TerrainGraph.Type.OUTPUT,520,20);g.connect(trees.id,output.id,0);return g;}
 public static void main(String[] args)throws Exception{
  var c=TreeLibrary.catalog();check(c.trees().size()==370&&c.groups().size()==29,"catalog and source cell count");int voxels=0;for(var tree:c.trees()){check(c.byGroup().get(tree.group).contains(tree),"group membership");voxels+=tree.states.length;for(int state:tree.states)check(state>=0&&state<c.states().size(),"palette index");}check(voxels==343774,"all converted tree voxels");for(var state:c.states()){check(!state.name().contains("command")&&!state.name().contains("sign"),"controller blocks excluded");if(state.name().endsWith("_leaves"))check(state.properties().get("persistent").equals("true"),"persistent foliage");}
  var g=forest();var trees=g.nodes.get(2);var a=g.evaluate(128,128,63,42,g.output(),()->false);var b=g.evaluate(128,128,63,42,g.output(),()->false);check(a.environment().trees.size()>0&&a.environment().trees.equals(b.environment().trees),"deterministic scatter");int selected=TreeLibrary.selected(trees).id;for(var p:a.environment().trees)check(p.tree()==selected,"one selected variant, no group mixing");
  trees.values.put("seed",2.0);var changed=g.evaluate(128,128,63,42,g.output(),()->false);check(!a.environment().trees.equals(changed.environment().trees),"seed changes placement");for(var p:changed.environment().trees)check(p.tree()==selected,"new seed keeps exact variant");
  trees.values.put("group",1.0);trees.values.put("variant",0.0);var other=g.evaluate(128,128,63,42,g.output(),()->false);for(var p:other.environment().trees)check(c.trees().get(p.tree()).group==1,"chosen group only");trees.values.put("group",0.0);trees.values.put("density",0.0);check(g.evaluate(128,128,63,42,g.output(),()->false).environment().trees.isEmpty(),"density zero");trees.values.put("density",1.0);
  var mask=g.add(TerrainGraph.Type.HEIGHT_MASK,0,0);g.connect(1,mask.id,0);mask.values.put("min",90.0);mask.values.put("max",110.0);g.connect(mask.id,trees.id,1);check(g.evaluate(128,128,63,42,g.output(),()->false).environment().trees.isEmpty(),"density mask excludes region");trees.input[1]=-1;g.nodes.get(1).values.put("height",40.0);check(g.evaluate(128,128,63,42,g.output(),()->false).environment().trees.isEmpty(),"no submerged placement");
  var w=new TerraForge.World(32,63,42);Arrays.fill(w.height,80);w.environment.trees=List.of(new TreeLibrary.Placement(0,15,15,1));var spatial=new TreeLibrary.SpatialIndex(w);int blocks=0;for(int z=0;z<2;z++)for(int x=0;x<2;x++)for(int value:spatial.overlay(x,z))if(value>0)blocks++;check(blocks==c.trees().get(0).states.length,"complete rotated tree across four chunks");
  boolean rotated=false;for(int id=0;id<c.states().size();id++)if(c.states().get(id).properties().getOrDefault("axis","").equals("x")){check(TreeLibrary.state(22+id*4+1).properties().get("axis").equals("z"),"rotated log axis");rotated=true;break;}check(rotated,"branch axis fixture present");
  Path file=Files.createTempFile("tree-project-",".terra");w.graph=forest();TerraForge.writeProject(w,file);var restored=TerraForge.readProject(file);check(restored.environment.trees.equals(w.environment.trees)&&restored.graph.nodes.get(2).type==TerrainGraph.Type.TREES,"project persists selected trees and graph");Files.delete(file);
  // Pre-tree version 4 environment records had no placement list.
  var legacyWorld=new TerraForge.World(32,63,42);Arrays.fill(legacyWorld.height,80);legacyWorld.environment.water=EnvironmentMap.filled(1024,70);ByteArrayOutputStream envBytes=new ByteArrayOutputStream();legacyWorld.environment.write(new DataOutputStream(envBytes));Path legacyFile=Files.createTempFile("legacy-v4-",".terra");try(DataOutputStream d=new DataOutputStream(new java.util.zip.GZIPOutputStream(Files.newOutputStream(legacyFile)))){d.writeUTF("TERRAFORGE4");d.writeInt(32);d.writeInt(63);d.writeLong(42);for(float h:legacyWorld.height)d.writeFloat(h);d.write(legacyWorld.material);legacyWorld.settings.write(d);d.writeUTF("Island");d.writeInt(85);d.writeBoolean(false);d.write(envBytes.toByteArray(),0,envBytes.size()-4);}var legacy=TerraForge.readProject(legacyFile);check(legacy.environment.trees.isEmpty()&&legacy.environment.water[0]==70,"version 4 environment compatibility");Files.delete(legacyFile);
  ByteArrayOutputStream stamp=new ByteArrayOutputStream();forest().write(new DataOutputStream(stamp));byte[] graphBytes=stamp.toByteArray();graphBytes[6]=(byte)(graphBytes[6]=='0'?'1':'0');boolean mismatch=false;try{TerrainGraph.read(new DataInputStream(new ByteArrayInputStream(graphBytes)));}catch(IOException expected){mismatch=true;}check(mismatch,"graph library revision mismatch rejected");
  stamp.reset();TreeLibrary.writePlacements(new DataOutputStream(stamp),w.environment.trees);byte[] placementBytes=stamp.toByteArray();placementBytes[6]=(byte)(placementBytes[6]=='0'?'1':'0');mismatch=false;try{TreeLibrary.readPlacements(new DataInputStream(new ByteArrayInputStream(placementBytes)),32);}catch(IOException expected){mismatch=true;}check(mismatch,"placed forest library revision mismatch rejected");
  EnvironmentView.render(w,0);check(w.treeHeights!=null&&Arrays.stream(w.treeHeights).max().orElse(0)>80,"canopy in preview height");check(TreeLibrary.thumbnail(c.trees().get(0)).getWidth()==220,"variant thumbnail");
  System.out.println("PASS: 370 variants/29 groups, complete voxel count, fixed selection, seeded placement, group isolation, masks, underwater exclusion, rotated cross-chunk trees, axes, persistence and preview");
  if(args.length>0){Path output=Path.of(args[0]);TerraForge.writeWorld(w,output);TerraForge.writeProject(w,Path.of(args[0]+".terra"));StringBuilder json=new StringBuilder("[");var t=c.trees().get(0);for(int i=0;i<t.states.length;i++){if(i>0)json.append(',');int x=15+TreeLibrary.rx(t.x[i],t.z[i],1),z=15+TreeLibrary.rz(t.x[i],t.z[i],1),y=81+t.y[i];TreeLibrary.State state=TreeLibrary.state(22+t.states[i]*4+1);json.append("["+x+","+y+","+z+",\""+state.name()+"\"]");}Files.writeString(Path.of(args[0]+".expected.json"),json.append(']').toString());}
 }
}
